const konuId = $('Split Out').first().json.KonuId;
const slideCount = $('Split Out').first().json.SlideCount;
const saniyeBundle = $('Split Out').first().json.SaniyeBundle;

const base = "C:/Users/busra/OneDrive/Desktop/AlevPenceOtomasyonu/Proje/Konular";
const konuPath = `${base}/Konu${konuId}`;
const imgDir = `${konuPath}/Görseller`;
const textDir = `${konuPath}/Slidelar`;
const audioPath = `${konuPath}/Ses${konuId}.mp3`;
const outputPath = `C:/Users/busra/OneDrive/Desktop/AlevPenceOtomasyonu/Proje/VideoBölümler/output${konuId}.mp4`;

function fixPath(p) {
  let s = p.replace(/\\/g, "/");
  s = s.replace(/:/, "\\:");
  return s;
}

const fontFileEscaped = fixPath("C:\\Windows\\Fonts\\calibrib.ttf");

const imageInputs = [];
for (let i = 1; i <= slideCount; i++) {
  const dur = saniyeBundle[i - 1];
  const imgPath = `${imgDir}/GorselSlide${i}.jpg`;
  imageInputs.push(`-loop 1 -t ${dur} -i "${imgPath}"`);
}

const filterBlocks = [];
for (let i = 1; i <= slideCount; i++) {
  const idx = i - 1;
  const txtPathRaw = `${textDir}/Slide${i}.txt`;
  const txtPath = fixPath(txtPathRaw);

  const block = `[${idx}:v]scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,setsar=1,format=yuv420p,` +
    `drawbox=x=0:y=0:w=iw:h=ih:color=white@0.3:t=fill,` +
    `drawtext=fontfile='${fontFileEscaped}':textfile='${txtPath}':fontcolor=white:fontsize=32:` +
    `x=(w-text_w)/2:y=(h-text_h)/2:shadowcolor=black:shadowx=4:shadowy=4:box=1:` +
    `boxcolor=black@0.6:boxborderw=50:line_spacing=4[v${idx}]`;

  filterBlocks.push(block);
}

const vChain = Array.from({ length: slideCount }, (_, k) => `[v${k}]`).join("");
const concatFilter = `${vChain}concat=n=${slideCount}:v=1:a=0,format=yuv420p[video]`;

const filterComplex = filterBlocks.join(";") + ";" + concatFilter;

const mapLine = `-map "[video]" -map ${slideCount}:a`;
const codecLine = `-c:v libx264 -c:a aac -b:a 192k -shortest "${outputPath}"`;

const ffmpegCommand =
  "ffmpeg " +
  imageInputs.join(" ") + " " +
  `-i "${audioPath}" ` +
  `-filter_complex "${filterComplex}" ` +
  `${mapLine} ` +
  `${codecLine}`;

return [{ json: { ffmpegCommand } }];
